import psycopg2, psycopg2.extras, os, json, base64, gzip
data = json.loads(gzip.decompress(base64.b64decode("")))
conn = psycopg2.connect(os.environ['DATABASE_URL'], cursor_factory=psycopg2.extras.RealDictCursor)
cur = conn.cursor()
imp = upd = skip = 0
for r in data:
    reg,epic_reg,epic_status,notary,reg_date,doc_stage,doc_status,notary_login,login_id,login_pwd,sq1,sa1,sq2,sa2,sq3,sa3,sq4,sa4,epic_id,notary_pwd = r
    cur.execute("SELECT registration_number FROM plab_clients WHERE registration_number = %s", (reg,))
    if not cur.fetchone():
        skip += 1; continue
    rd = reg_date if reg_date else None
    cur.execute("SELECT id FROM ops_epic_registration WHERE registration_number = %s", (reg,))
    ex = cur.fetchone()
    if ex:
        cur.execute("UPDATE ops_epic_registration SET epic_registration=%s, epic_status=%s, notary_camp=%s, registration_date=%s, documents_stage=%s, document_stage_status=%s, login_id=%s, login_pwd=%s, secret_question_1=%s, secret_answer_1=%s, secret_question_2=%s, secret_answer_2=%s, secret_question_3=%s, secret_answer_3=%s, secret_question_4=%s, secret_answer_4=%s, epic_id_number=%s, notary_camp_login=%s, notary_camp_password=%s WHERE id=%s",
            (epic_reg, epic_status, notary, rd, doc_stage, doc_status, login_id, login_pwd, sq1, sa1, sq2, sa2, sq3, sa3, sq4, sa4, epic_id, notary_login, notary_pwd, ex['id']))
        upd += 1
    else:
        cur.execute("INSERT INTO ops_epic_registration (registration_number, epic_registration, epic_status, notary_camp, registration_date, documents_stage, document_stage_status, login_id, login_pwd, secret_question_1, secret_answer_1, secret_question_2, secret_answer_2, secret_question_3, secret_answer_3, secret_question_4, secret_answer_4, epic_id_number, notary_camp_login, notary_camp_password, created_by) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
            (reg, epic_reg, epic_status, notary, rd, doc_stage, doc_status, login_id, login_pwd, sq1, sa1, sq2, sa2, sq3, sa3, sq4, sa4, epic_id, notary_login, notary_pwd, 0))
        imp += 1
conn.commit()
print(f"EPIC: {imp} new, {upd} updated, {skip} skipped")
cur.execute("SELECT COUNT(*) as c FROM ops_epic_registration"); print("Total EPIC:", cur.fetchone()['c'])
conn.close()
